INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63562593', 63562593, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Bidang Penuntasan TBC', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 99960000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Pembangunan Bidang Penuntasan TBC memiliki keluaran berupa Laporan Akhir Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Pembangunan Bidang Penuntasan TBC dengan waktu penyelesaian dibagi dalam 6 termin pembayaran (11 Bulan), rincian sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan Data Dukung Mekanisme Sinergi MRPN dalam Pengendalian dan Evaluasi Bidang Penuntasan TBC 2 Termin 2 Laporan Analisis MRPN Bidang Penuntasan TBC dalam Evaluasi TW I 3 Termin 3 Laporan Hasil Crosscheck Risiko dan Mitigasi TW I Bidang Penuntasan TBC 4 Termin 4 Laporan Analisis MRPN Bidang Penuntasan TBC untuk Pengendalian TW II 5 Termin 5 Laporan Penyiapan Analisis Manajemen Risiko TW III Bidang Penuntasan TBC 6 Termin 6 Laporan Akhir Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Pembangunan Bidang Penuntasan TBC', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Pembangunan Bidang Penuntasan TBC adalah sebagai berikut: 1. Menyusun mekanisme sinergi dan integrasi MRPN dengan pengendalian dan evaluasi program prioritas presiden bidang penuntasan TBC; 2. Menyusun analisis MRPN pada bidang penuntasan TBC sebagai bahan pendukung pengendalian dan evaluasi program prioritas presiden; 3. Melakukan identifikasi, analisis, validasi, dan mitigasi berdasarkan data pelaporan; 4. Menyusun laporan hasil analisis MRPN dan merumuskan usulan intervensi pengendalian pembangunan pada periode selanjutnya; 5. Melakukan review atas risiko pembangunan serta menyusun usulan rekomendasi kebijakan berbasis risiko untuk mendukung pencapaian sasaran program prioritas presiden bidang penuntasan TBC.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1002353);
