INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63579716', 63579716, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Alat/Bahan Medis Habis Pakai', 'Barang', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 20092793873, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Belanja alat dan bahan medis habis pakai merupakan kegiatan pengadaan perlengkapan medis yang digunakan langsung dalam pelayanan kesehatan di RSUD Kota Banjar. Kegiatan ini bertujuan untuk menjamin ketersediaan alat dan bahan medis habis pakai yang aman, bermutu, dan sesuai standar pelayanan rumah sakit guna mendukung pelayanan rawat jalan, rawat inap, dan gawat darurat secara berkesinambungan.', 'Pengadaan alat dan bahan medis habis pakai untuk mendukung pelayanan rawat jalan, rawat inap, dan gawat darurat di RSUD Kota Banjar. Produk yang disediakan harus memenuhi standar mutu dan keselamatan serta memiliki izin edar resmi sesuai ketentuan yang berlaku. Pelaksanaan pengadaan didasarkan pada perencanaan kebutuhan pelayanan rumah sakit. Proses penerimaan, penyimpanan, dan pendistribusian dilaksanakan sesuai standar kefarmasian dan alat kesehatan. Kegiatan ini bertujuan menjamin ketersediaan BMHP yang aman, bermutu, dan berkesinambungan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1003945);
