INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63563790', 63563790, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan BMHP Skrining Hipotiroid Kongenital Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 181567558000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda; Menyediakan BMHP Skrining Hipotiroid Kongenital berupa Kertas saring khusus untuk skrining bayi baru lahir beserta Plastic zip lock, Lancet pediatrik dengan ujung mata pisau (tipe Blade) dan kedalaman tusukan 2 mm, Alcohol Swab, Silica Gel', 'Spesifikasi BMHP Skrining Hipotiroid Kongenital sebagai berikut: A. Kertas Saring a. Kertas saring untuk penggunaan skrining bayi baru lahir b. Jenis kertas filter: serat kapas murni. c. Penyedia menyampaikan dokumen yang menyatakan bahwa kertas saring memenuhi spesifikasi PH 5,7-7,5, %Ash: Maksimum 0,1%, Waktu absorpsi: range: 5 - 30 detik, Berat dasar: 110 lb ± 5% (179 g/m2 ± 5%) per rim2 dari 61- x 91-cm lembar d. Terdapat lima lubang dengan diameter Dried Blood Spot: 14 – 17 mm. Kelima lubang dapat digunakan. e. Kartu kertas saring terbuat dari karton tebal yang berukuran minimal 10 x 18 cm dan dilengkapi dengan plastik zip lock dengan ukuran sesuai. f. Kartu kertas saring berisi tulisan informasi antara lain identitas bayi, identitas orangtua, nama fasyankes, nama kabupaten/kota, nama dan nomor telpon dokter penanggung jawab, keterangan spesimen, kondisi bayi, riwayat terapi pada ibu sumber pembiayaan, instruksi singkat pengambilan darah dan gambar, serta tulisan APBN 2025 pada bagian belakang-bawah. g. Produk memiliki TKDN/Produk Dalam Negeri dan memiliki izin edar yang diterbitkan oleh Kementerian Kesehatan h. Telah mendapatkan rekomendasi tim ahli yg di keluarkan pada tahun 2025. B. Lancet Pediatrik 1. Lancet steril sekali pakai untuk mengambil darah kapiler pada bayi 2. Ujung lancet berbentuk pisau (blade tip lancet) dari bahan stainless steel. 3. Kedalaman tusukan (depth) 2 mm 4. Kemasan lancet dari plastik 5. Expired date / tanggal kadaluwarsa minimal 24 bulan saat diterima di Dinkes Kab/Kota. 6. Lancet secara otomatis masuk ke dalam perangkat (auto retract) 7. Produk memiliki TKDN/Produk Dalam Negeri dan memiliki izin edar yang diterbitkan oleh Kementerian Kesehatan Tampak Depan Tampak Belakang APBN 2026. C. Alkohol Swab 1. Bahan dasar: Non woven/katun mengandung alkohol 70%. 2. Hanya untuk pemakaian luar dan sekali pakai. 3. Kemasan: Box, Satuan terbungkus dengan aluminium foil 4. Suhu penyimpanan: maksimal 30 derajat celcius 5. Expired date/ tanggal kadaluwarsa minimal 18 bulan saat diterima di Dinkes Kab/Kota. 6. Produk memiliki TKDN/Produk Dalam Negeri dan memiliki izin edar yang diterbitkan oleh Kementerian Kesehatan. D. Silica Gel 1. Bahan : Silikon Dioksida 2. (SiO2) Warna : Putih atau transparan 3. Bentuk : Butiran Bulat di dalam bahan kantong yang kuat 4. Berbahan aman atau tidak beracun Padat 5. Tidak berbau 6. Tidak berasa 7. Tidak mudah larut 8. Tidak mudah terbakar 9. Stabil pada suhu tinggi dan rendah 10. Berfungsi menjaga atau menyerap kelembaban 11. Jenis : silica gel putih atau silica natural 12. Yang paling umum : silica gel putih (white) Catatan Khusus: 1. Spesifikasi didukung oleh dokumen yang valid 2. Jika diperlukan, barang dapat diuji oleh penyelenggara seleksi pengadaan / user 3. Dilengkapi dokumen surat pernyataan / menjamin dari penyedia bahwa penyedia bertanggung jawab keaslian barang yang didistribusi. 4. Usulan kebutuhan BMHP disesuaikan dengan kemasan yang ada di pasaran', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1007139);
